قين يخلص النفوس من الأنانية ويحملها على التزام حدودها.","source":{"document_id":"islamic_education_g11_s2_2025","printed_pages":[120],"pdf_pages":[120]}},"uses":[[0],[2],[3],[5],[6],[10]]},{"data":{"id":"u03_l05_q004","unit_id":"u03","lesson_id":"u03_l05","difficulty":"easy","type":"multiple_choice","prompt":"ما أساس الزوجية المعتبرة سببا للإرث في النص؟","topic":"المفهوم والحكمة والأسباب","payload":{"options":[{"id":"o1","text":"مجرد الجوار"},{"id":"o2","text":"عقد زواج صحيح"},{"id":"o3","text":"مجرد الخطبة"},{"id":"o4","text":"الوعد بالزواج"}]},"answer":{"option_id":"o2"},"explanation":"عرف الدرس الزوجية بأنها العلاقة الناشئة عن عقد زواج صحيح.","source":{"document_id":"islamic_education_g11_s2_2025","printed_pages":[120],"pdf_pages":[120]}},"uses":[[0],[2],[3],[5],[6],[10]]},{"data":{"id":"u03_l05_q007","unit_id":"u03","lesson_id":"u03_l05","difficulty":"medium","type":"multiple_choice","prompt":"لم يقدم سداد الدين على تنفيذ الوصية؟","topic":"أحكام التركة","payload":{"options":[{"id":"o1","text":"لأن الوصية تنفذ أولا دائما"},{"id":"o2","text":"لأن الدين يسقط بالموت"},{"id":"o3","text":"لأنه تبرع اختياري"},{"id":"o4","text":"لأنه حق واجب على الإنسان"}]},"answer":{"option_id":"o4"},"explanation":"علل الهامش التقديم بأن الدين حق واجب.","source":{"document_id":"islamic_education_g11_s2_2025","printed_pages":[121],"pdf_pages":[121]}},"uses":[[0],[2],[3],[5],[6],[10]]},{"data":{"id":"u03_l05_q008","unit_id":"u03","lesson_id":"u03_l05","difficulty":"hard","type":"multiple_choice","prompt":"كيف يميز الكتاب بين التقديم في ألفاظ آية الميراث وترتيب التنفيذ الفعلي؟","topic":"أحكام التركة","payload":{"options":[{"id":"o1","text":"تقديم الدين في التنفيذ يلغي الوصية ولو صحت شرعًا"},{"id":"o2","text":"تقديم الوصية لفظًا يوجب تنفيذها قبل قضاء الدين"},{"id":"o3","text":"تقديم الوصية لفظًا يجعلها أسبق من تجهيز الميت ودفنه"},{"id":"o4","text":"تقديم الوصية لفظًا للتأكيد عليها مع قضاء الدين أولًا في التنفيذ"}]},"answer":{"option_id":"o4"},"explanation":"تبين صفحة 121 أن تقديم لفظ الوصي